import numpy as np
from scipy.optimize import minimize

def solve_optimization(n):
    L = 2 / np.sqrt(n)

    # Objective function: minimize -S2 = -sum(a_i^2)
    def objective(a):
        return -np.sum(a**2)

    # Equality constraint: sum(a_i^3) = 0
    def constraint_eq(a):
        return np.sum(a**3)

    # Inequality constraints: a_i <= L (n constraints)
    # Scipy minimize handles inequality constraints as g(x) >= 0.
    # We want a_i <= L, which is L - a_i >= 0.
    constraints = []
    for i in range(n):
        constraints.append({
            'type': 'ineq',
            'fun': lambda a, i=i: L - a[i]
        })

    # We also need to provide bounds. Since we want to maximize S2, 
    # we expect both positive and negative values. The positive ones are bounded by L.
    # The negative ones are constrained by the cube sum, but we need a search range.
    # Let's use a symmetric bound for safety, say [-2*L, L].
    bounds = [(-2 * L, L)] * n

    # Initial guess: distribute the capacity equally, balancing positive/negative contributions.
    # A simple guess might be a vector close to zero.
    x0 = np.zeros(n)

    # Optimization using Sequential Least Squares Programming (SLSQP) or COBYLA
    # SLSQP handles both equality and inequality constraints well.
    result = minimize(objective, x0, method='SLSQP', 
                      constraints=constraints, bounds=bounds)

    if result.success:
        max_s2 = -result.fun
        return max_s2, result.x
    else:
        return None, None

# Test for n = 2, 3, 4, 5
results = {}
for n in [2, 3, 4, 5]:
    max_s2, a_config = solve_optimization(n)
    if max_s2 is not None:
        results[n] = (max_s2, a_config)
    else:
        results[n] = "Optimization failed"

print(results)

